function standings(){let rows=clubs.map(c=>({name:c.name,crest:c.crest,pts:0,w:0,d:0,l:0,gf:0,ga:0,form:[],ours:c.ours}));for(const m of state.played){const home=rows.find(x=>x.name===m.home),away=rows.find(x=>x.name===m.away);home.gf+=m.hg;home.ga+=m.ag;away.gf+=m.ag;away.ga+=m.hg;if(m.hg>m.ag){home.pts+=3;home.w++;away.l++;home.form.push('W');away.form.push('L')}else if(m.hg<m.ag){away.pts+=3;away.w++;home.l++;away.form.push('W');home.form.push('L')}else{home.pts++;away.pts++;home.d++;away.d++;home.form.push('D');away.form.push('D')}}return rows.sort((a,b)=>b.pts-a.pts||(b.gf-b.ga)-(a.gf-a.ga)||b.gf-a.gf)}
function leagueTable(){const rows=standings();return `<table class="league-table"><thead><tr><th>#</th><th>CLUB</th><th>P</th><th>GD</th><th>PTS</th><th>FORM</th></tr></thead><tbody>${rows.slice(0,6).map((r,i)=>`<tr class="${r.ours?'our-row':''}"><td><span class="position">${i+1}</span></td><td><span class="club-cell"><span class="mini-crest">${r.crest}</span>${r.name.replace(/ FC| Town| United| Athletic| Rovers| City| Albion| County| Wanderers/,'')}</span></td><td>${r.w+r.d+r.l}</td><td>${r.gf-r.ga>0?'+':''}${r.gf-r.ga}</td><td>${r.pts}</td><td><span class="form-balls">${(r.form.slice(-3).length?r.form.slice(-3):['·']).map(x=>`<i class="${x.toLowerCase()}">${x}</i>`).join('')}</span></td></tr>`).join('')}</tbody></table>`}
function pitchMarkup(detailed=false){const ids=state.lineup.map(player).filter(Boolean);const rows=[ids.filter(p=>p.pos==='ATT').slice(0,1),ids.filter(p=>p.pos==='ATT').slice(1,3).concat(ids.filter(p=>p.pos==='MID').slice(2,3)),ids.filter(p=>p.pos==='MID').slice(0,2),ids.filter(p=>p.pos==='DEF').slice(0,4),ids.filter(p=>p.pos==='GK').slice(0,1)];return `<div class="pitch${detailed?' detailed-pitch':''}"><span class="halfway"></span><span class="penalty left"></span><span class="penalty right"></span><div class="formation-grid">${rows.map((row,ri)=>`<div class="formation-row">${row.map(p=>`<div class="player-chip ${p.pos==='GK'?'keeper':''}" title="${escapeHtml(p.name)} · ${p.rating} OVR" data-player="${p.id}"><span class="player-shirt">${p.rating}</span><span class="player-name">${escapeHtml(p.name.split(' ').slice(-1)[0])}</span><span class="player-pos">${p.pos}</span></div>`).join('')}</div>`).join('')}</div></div>`}
function nextMatchCard(){const opp=nextOpponent();return `<section class="panel"><div class="panel-heading"><h2>Next fixture</h2><span class="tag">UP NEXT</span></div><div class="next-match"><div class="match-topline"><span>MATCHDAY ${String(state.round).padStart(2,'0')}</span><span class="countdown">${state.round===1?'SEASON OPENER':'7 DAYS'}</span></div><div class="matchup"><div class="team"><div class="team-crest">⚒</div><strong>Riverside FC</strong><small>HOME</small></div><div class="versus">VS</div><div class="team"><div class="team-crest opponent">${opp.crest}</div><strong>${opp.name}</strong><small>AWAY</small></div></div><div class="match-details"><span>🏟 <strong>Riverside Park</strong></span><span>⏱ <strong>15:00</strong></span></div><div class="match-footer"><div class="form-mini">${formMini()}</div><button class="button primary small" id="play-match">Play match <span>→</span></button></div></div></section>`}
