function overview(){const starter=state.lineup.map(player).filter(Boolean);return `<div class="page-head"><div><div class="eyebrow">SATURDAY, ${String(matchDayDate(state.round).getDate()).padStart(2,'0')} AUGUST · NORTHBRIDGE LEAGUE</div><h1>Good morning, Jordan <span>👋</span></h1><p>Season opener is around the corner. The squad is ready when you are.</p></div><div class="head-actions"><button class="button" data-action="training">⚡ Run training</button><button class="button primary" id="play-match">Team talk &amp; play&nbsp; →</button></div></div><div class="grid-main"><section class="panel squad-panel"><div class="panel-heading"><div><h2>Matchday squad</h2><span class="sub">Starting XI · ${state.tactic.formation}</span></div><button class="button small" data-view="squad">Manage squad ↗</button></div><div class="pitch-wrap">${pitchMarkup()}<div class="pitch-caption"><span><strong>Riverside FC</strong> · Average rating ${Math.round(starter.reduce((a,p)=>a+p.rating,0)/Math.max(1,starter.length))}</span><span>Click a player to manage your XI</span></div><div class="pitch-tip">Your tactical shape: <strong>${state.tactic.mentality}</strong> · ${state.tactic.press} press · ${state.tactic.focus} focus</div></div></section><div class="right-stack">${nextMatchCard()}<section class="panel standings-panel"><div class="panel-heading"><h2>League table</h2><button class="table-link" data-view="fixtures">Full table ↗</button></div>${leagueTable()}</section></div></div><section class="panel news-panel"><div class="panel-heading"><h2>Clubhouse</h2><span class="sub">LATEST UPDATES</span></div><div class="news-list"><div class="news-item"><span class="news-icon">✦</span><div class="news-copy"><strong>Season expectations</strong><p>The board wants a top-half finish. A strong start will settle the nerves.</p></div></div><div class="news-item"><span class="news-icon">♧</span><div class="news-copy"><strong>Fitness report</strong><p>${fitSummary()}</p></div></div><div class="news-item"><span class="news-icon">◉</span><div class="news-copy"><strong>From the press room</strong><p>${escapeHtml(state.lastNews)}</p></div></div></div></section>`}
function fitSummary(){const low=state.lineup.map(player).filter(p=>p&&p.fitness<80);return low.length?`${low.map(p=>p.name.split(' ')[0]).join(', ')} could use a rest before kickoff.`:'The starting XI are all fit and training well.'}
function positionClass(pos){return ({GK:'Goalkeeper',DEF:'Defender',MID:'Midfielder',ATT:'Forward'})[pos]||pos}
function squad(){return `<div class="page-head"><div><div class="eyebrow">FIRST TEAM · ${state.players.length} PLAYERS</div><h1>The squad</h1><p>Build your matchday XI and keep an eye on fitness, form and potential.</p></div><div class="head-actions"><button class="button" data-action="training">⚡ Run training</button><button class="button primary" data-view="tactics">Set tactics&nbsp; →</button></div></div><section class="panel content-panel"><div class="squad-toolbar"><input id="player-search" class="search-input" placeholder="⌕  Search players..." aria-label="Search players"><select id="position-filter" class="select-input"><option value="all">All positions</option><option value="GK">Goalkeepers</option><option value="DEF">Defenders</option><option value="MID">Midfielders</option><option value="ATT">Forwards</option></select><div class="toolbar-spacer"></div><span class="muted">${state.lineup.length} / 11 selected</span></div><table class="squad-table"><thead><tr><th>PLAYER</th><th>POS</th><th>AGE</th><th>OVR</th><th>FITNESS</th><th>MORALE</th><th></th></tr></thead><tbody id="squad-rows">${squadRows()}</tbody></table></section><div class="page-head" style="margin-top:19px"><div><div class="eyebrow">SELECTION TIP</div><p>Use <strong style="color:#dce7dc">Select</strong> to swap a player into the XI. Keep your best players fresh for matchday.</p></div></div>`}
function squadRows(filter='all',search=''){let list=state.players.filter(p=>(filter==='all'||p.pos===filter)&&p.name.toLowerCase().includes(search.toLowerCase())).sort((a,b)=>(['GK','DEF','MID','ATT'].indexOf(a.pos)-['GK','DEF','MID','ATT'].indexOf(b.pos))||b.rating-a.rating);return list.map(p=>{const selected=state.lineup.includes(p.id);return `<tr><td><div class="player-main"><span class="player-avatar">${p.name.split(' ').map(n=>n[0]).join('')}</span><div><strong>${escapeHtml(p.name)}</strong><small>${selected?'Starting XI':'Squad player'}</small></div></div></td><td><span class="pos-badge">${p.pos}</span></td><td>${p.age}</td><td><span class="rating">${p.rating}</span><span class="stat-bar"><i style="width:${p.rating}%"></i></span></td><td class="${p.fitness<75?'injury':'fitness'}">${p.fitness}%</td><td>${p.morale} <span style="color:#76867c">↗</span></td><td><button class="action-text" data-select-player="${p.id}">${selected?'In XI':'Select'}</button></td></tr>`}).join('')||`<tr><td colspan="7" class="empty-state">No players match your search.</td></tr>`}
function tactics(){return `<div class="page-head"><div><div class="eyebrow">TACTICAL ROOM</div><h1>Make the plan</h1><p>Shape your team's identity. Your choices influence how the match plays out.</p></div><div class="head-actions"><button class="button primary" id="play-match">Team talk &amp; play&nbsp; →</button></div></div><div class="tactic-layout"><section class="panel tactic-board"><div class="panel-heading"><div><h2>Shape &amp; roles</h2><span class="sub">${state.lineup.length} players selected</span></div><span class="tag">${state.tactic.formation}</span></div><div class="pitch-wrap">${pitchMarkup(true)}<div class="pitch-caption"><span>Tap any player to manage your XI</span><strong>Riverside FC</strong></div></div></section><section class="panel"><div class="panel-heading"><h2>Team instructions</h2><span class="sub">ACTIVE TACTICS</span></div><div class="tactic-controls">${choiceGroup('Formation','formation',['4-2-3-1','4-3-3','4-4-2'])}${choiceGroup('Mentality','mentality',['Defensive','Balanced','Attacking'])}${choiceGroup('Pressing intensity','press',['Low block','Standard','High press'])}${choiceGroup('Attacking focus','focus',['Mixed','Wings','Through balls'])}<div class="control-group"><label>TACTICAL NOTE</label><div class="tactic-note">${tacticNote()}</div></div></div></section></div>`}
function choiceGroup(label,key,options){return `<div class="control-group"><label>${label.toUpperCase()}</label><div class="choice-row">${options.map(o=>`<button class="choice ${state.tactic[key]===o?'selected':''}" data-tactic="${key}" data-value="${o}">${o}</button>`).join('')}</div></div>`}
function tacticNote(){return state.tactic.mentality==='Attacking'?'Push forward and commit numbers. Expect more chances, but leave space in behind.':state.tactic.mentality==='Defensive'?'Stay compact and frustrate the opposition. You may need to be patient on the ball.':state.tactic.press==='High press'?'Hunt the ball high up the pitch. Your players will tire faster, but turnovers can be dangerous.':state.tactic.focus==='Wings'?'Get the ball wide and stretch their back line. Your wingers will be key to creating chances.':'A flexible setup that keeps your team balanced in every phase of play.'}
function fixtures(){const hist=state.played.slice().reverse().map(m=>({day:m.day,home:m.home,away:m.away,score:`${m.hg} – ${m.ag}`,played:true}));let upcoming=[];for(let i=state.round;i<=18;i++){const opponent=clubs[(i-1)%9+1];upcoming.push({day:i,home:'Riverside FC',away:opponent.name,played:false})}return `<div class="page-head"><div><div class="eyebrow">NORTHBRIDGE LEAGUE · 2025/26</div><h1>Fixtures &amp; table</h1><p>Every point counts. Your next challenge is right around the corner.</p></div><div class="head-actions"><button class="button primary" id="play-match">Play next match&nbsp; →</button></div></div><div class="grid-main"><section class="panel"><div class="panel-heading"><h2>League table</h2><span class="sub">MATCHDAY ${state.round-1} OF 18</span></div>${leagueTable()}</section><section class="panel"><div class="panel-heading"><h2>Season snapshot</h2></div><div class="next-match"><div class="match-topline"><span>RIVERSIDE FC</span><span class="countdown">${state.played.length?`${standings().find(r=>r.ours).pts} POINTS`:'READY TO BEGIN'}</span></div><div style="font:600 19px var(--display);margin:14px 0 7px">${standings().findIndex(r=>r.ours)+1}<span style="font-size:11px;color:#85968a">${ordinal(standings().findIndex(r=>r.ours)+1)} place</span></div><div class="muted">${state.played.length} played · ${standings().find(r=>r.ours).w} wins · ${standings().find(r=>r.ours).d} draws · ${standings().find(r=>r.ours).l} losses</div><div class="progress-track" style="margin-top:15px"><i style="width:${(state.played.length/18)*100}%"></i></div></div></section></div><section class="panel" style="margin-top:15px"><div class="panel-heading"><h2>Season schedule</h2><span class="sub">${state.played.length} COMPLETED · 18 TOTAL</span></div><div class="fixture-list">${hist.map(fixtureRow).join('')}${upcoming.map(fixtureRow).join('')}</div></section>`}
function ordinal(n){return n===1?'st':n===2?'nd':n===3?'rd':'th'}
function fixtureRow(f){const d=matchDayDate(f.day);return `<div class="fixture-row"><div class="fixture-date">MD ${String(f.day).padStart(2,'0')}<br>${d.toLocaleDateString('en-GB',{day:'numeric',month:'short'}).toUpperCase()}</div><div class="fixture-teams"><strong>${f.home}</strong><span>vs</span><strong>${f.away}</strong></div><div class="fixture-score">${f.played?f.score:'— : —'}</div><div class="fixture-status ${f.played?'':'next'}">${f.played?'FULL TIME':f.day===state.round?'UP NEXT':'UPCOMING'}</div></div>`}
const transferTargets=[{name:'Mateo Silva',pos:'MID',age:20,rating:72,fee:2.4,club:'Porto Vale'},{name:'Charlie Webb',pos:'DEF',age:22,rating:70,fee:1.8,club:'Free agent'},{name:'André Costa',pos:'ATT',age:24,rating:74,fee:3.2,club:'Santa Lucia'},{name:'Milo Varga',pos:'GK',age:19,rating:68,fee:1.1,club:'Danubia'},{name:'Isaac Rowe',pos:'ATT',age:21,rating:71,fee:2.1,club:'Free agent'}];
function transfers(){return `<div class="page-head"><div><div class="eyebrow">SCOUTING NETWORK</div><h1>Transfer market</h1><p>Find the missing piece. Your scouts have flagged a few names to watch.</p></div></div><div class="transfer-grid"><section class="panel"><div class="panel-heading"><h2>Recommended players</h2><span class="sub">SCOUTING SHORTLIST</span></div>${transferTargets.map((p,i)=>{const bought=state.players.some(x=>x.name===p.name);return `<div class="fixture-row transfer-card"><div class="player-avatar">${p.name.split(' ').map(n=>n[0]).join('')}</div><div class="player-main"><div><strong>${p.name}</strong><small>${p.club} · Age ${p.age}</small></div></div><span class="pos-badge">${p.pos}</span><span class="rating">${p.rating}</span><span class="transfer-fee">£${p.fee.toFixed(1)}m</span><button class="buy-button" data-buy="${i}" ${bought||state.budget<p.fee?'disabled':''}>${bought?'SIGNED':state.budget<p.fee?'OVER BUDGET':'SIGN'}</button></div>`}).join('')}</section><section class="panel budget-card"><h3>Transfer budget</h3><span class="tag" style="justify-self:start">BOARD APPROVED</span><div class="budget-amount">£${state.budget.toFixed(1)}m</div><p>Available funds for the 2025/26 season. Choose wisely — wages also matter.</p><div class="budget-line"><span>Squad size</span><strong>${state.players.length} players</strong></div><div class="budget-line"><span>Board target</span><strong>Top half</strong></div><div class="budget-line"><span>Window closes</span><strong>31 Aug 2025</strong></div></section></div>`}
function render(){updateHeader();const view=document.getElementById('app-content');view.innerHTML=({overview,squad,tactics,fixtures,transfers}[activeView]||overview)();document.querySelectorAll('.nav-item[data-view]').forEach(n=>n.classList.toggle('active',n.dataset.view===activeView));document.getElementById('top-context').textContent=activeView.toUpperCase();bindViewEvents()}

function bindViewEvents(){document.querySelectorAll('[data-view]').forEach(el=>el.addEventListener('click',()=>{activeView=el.dataset.view;render()}));document.querySelectorAll('#play-match').forEach(el=>el.addEventListener('click',playMatch));document.querySelectorAll('[data-action="training"]').forEach(el=>el.addEventListener('click',runTraining));document.querySelectorAll('[data-tactic]').forEach(el=>el.addEventListener('click',()=>{state.tactic[el.dataset.tactic]=el.dataset.value;save();render()}));document.querySelectorAll('[data-select-player]').forEach(el=>el.addEventListener('click',()=>selectPlayer(Number(el.dataset.selectPlayer))));document.querySelectorAll('[data-buy]').forEach(el=>el.addEventListener('click',()=>signPlayer(Number(el.dataset.buy))));const search=document.getElementById('player-search'),filter=document.getElementById('position-filter');if(search&&filter){const update=()=>{document.getElementById('squad-rows').innerHTML=squadRows(filter.value,search.value);bindSelectEvents()};search.addEventListener('input',update);filter.addEventListener('change',update)}}
function bindSelectEvents(){document.querySelectorAll('[data-select-player]').forEach(el=>el.addEventListener('click',()=>selectPlayer(Number(el.dataset.selectPlayer))))}
function selectPlayer(id){if(state.lineup.includes(id)){showToast('That player is already in your starting XI.');return}const incoming=player(id);const candidates=state.lineup.map((pid,i)=>({p:player(pid),i})).filter(x=>x.p&&x.p.pos===incoming.pos);let out=candidates.sort((a,b)=>a.p.rating-b.p.rating)[0];if(!out){out=state.lineup.map((pid,i)=>({p:player(pid),i})).filter(x=>x.p&&x.p.pos!=='GK').sort((a,b)=>a.p.rating-b.p.rating)[0]}if(!out){showToast('No suitable player to replace.');return}state.lineup[out.i]=id;state.lastNews=`${incoming.name.split(' ')[0]} has been called into the starting XI.`;save();render();showToast(`${incoming.name} is in the starting XI.`)}
function runTraining(){if(state.trainedRound===state.round){showToast('Training is already complete for this matchday.');return}state.trainedRound=state.round;state.players.forEach(p=>{p.morale=Math.min(99,p.morale+2);p.fitness=Math.max(55,p.fitness-3);if(Math.random()<.14)p.rating=Math.min(90,p.rating+1)});state.lastNews='A sharp training session lifted spirits around the squad.';save();render();showToast('Training complete — morale is up, fitness is down slightly.')}
function signPlayer(index){const target=transferTargets[index];if(!target||state.budget<target.fee||state.players.some(p=>p.name===target.name))return;const id=Math.max(...state.players.map(p=>p.id))+1;state.players.push({id,name:target.name,pos:target.pos,age:target.age,rating:target.rating,fitness:100,morale:76,value:target.fee*.65});state.budget-=target.fee;state.lastNews=`${target.name} has joined Riverside FC. Welcome to the club!`;save();render();showToast(`${target.name} signed for £${target.fee.toFixed(1)}m.`)}
function randInt(min,max){return Math.floor(Math.random()*(max-min+1))+min}
function poisson(lambda){const limit=Math.exp(-lambda);let k=0,p=1;do{k++;p*=Math.random()}while(p>limit);return k-1}
function attackRating(){const starters=state.lineup.map(player).filter(Boolean);let avg=starters.reduce((s,p)=>s+p.rating,0)/Math.max(1,starters.length);const fitness=starters.reduce((s,p)=>s+p.fitness,0)/Math.max(1,starters.length);let tactic=state.tactic.mentality==='Attacking'?3:state.tactic.mentality==='Defensive'?-2:0;if(state.tactic.press==='High press')tactic+=1;if(fitness<75)tactic-=2;return avg+tactic}
