function schedule(){const order=clubs.map((_,i)=>i),rounds=[];for(let r=0;r<9;r++){const games=[];for(let i=0;i<5;i++){let a=order[i],b=order[9-i];if((r+i)%2)[a,b]=[b,a];games.push({home:clubs[a],away:clubs[b]})}rounds.push(games);order.splice(1,0,order.pop())}return rounds.flatMap((games,i)=>[games,{...games.map(g=>({home:g.away,away:g.home}))}]).slice(0,18)}
function fixture(round=state.round){return schedule()[Math.max(0,Math.min(17,round-1))]||[]}
function nextOpponent(){const game=fixture().find(g=>g.home.ours||g.away.ours);return game?.home.ours?game.away:game?.home||clubs[1]}

