function render(){const root=document.getElementById('app-content');if(!root)return;const views={overview,squad,tactics,fixtures,transfers};root.innerHTML=(views[activeView]||overview)();document.querySelectorAll('.nav-item[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===activeView));document.getElementById('top-context').textContent=activeView.toUpperCase();updateHeader();bindViewEvents()}
function train(){const gain=state.training==='Fitness'?7:4;state.players.forEach(p=>{p.fitness=Math.min(100,p.fitness+gain);p.morale=Math.min(100,p.morale+1)});state.lastNews=`The squad completed a ${state.training.toLowerCase()} session. Fitness and morale are looking sharper.`;save();render();showToast(`${state.training} training complete · squad fitness improved`)}
function selectPlayer(id){const p=player(id);if(!p)return;if(state.lineup.includes(id)){showToast(`${p.name} is already in the starting XI`);return}let target;if(state.lineup.length<11)state.lineup.push(id);else{const same=state.lineup.map(player).filter(x=>x&&x.pos===p.pos);if(p.pos==='GK'&&!same.length){showToast('Your starting XI needs a goalkeeper');return}target=(same.length?same:state.lineup.map(player).filter(x=>x&&x.pos!=='GK')).sort((a,b)=>a.rating-b.rating)[0];if(!target)return;state.lineup[state.lineup.indexOf(target.id)]=id}save();render();showToast(`${p.name} added to the starting XI`)}
function poisson(lambda){const limit=Math.exp(-lambda);let k=0,product=1;do{k++;product*=Math.random()}while(product>limit&&k<8);return k-1}
function teamPower(club){if(!club.ours)return club.strength;const selected=state.lineup.map(player).filter(Boolean);let avg=selected.reduce((sum,p)=>sum+p.rating*(p.fitness<70?.88:p.fitness<82?.95:1),0)/Math.max(1,selected.length);const mentality={Cautious:-2,Balanced:0,Positive:1,Attacking:2}[state.tactic.mentality]||0;return avg+mentality+(state.tactic.press==='High'?1:0)}
function simulateMatch(){if(state.round>18){showToast('The season is already complete');return}const round=state.round,games=fixture(round),events=[],results=[];for(const g of games){const delta=teamPower(g.home)-teamPower(g.away)+(g.home.ours?3:g.away.ours?-3:2);const hg=poisson(Math.max(.25,1.35*Math.exp(delta/21))),ag=poisson(Math.max(.2,1.15*Math.exp(-delta/21)));const result={round,home:g.home.name,away:g.away.name,hg,ag};results.push(result);for(let n=0;n<hg;n++)events.push({minute:Math.floor(4+Math.random()*87),home:true,team:g.home,name:g.home.ours?scorer(true):['Liam Foster','Marco Silva','Elliot James','Drew Cooper'][Math.floor(Math.random()*4)]});for(let n=0;n<ag;n++)events.push({minute:Math.floor(4+Math.random()*87),home:false,team:g.away,name:g.away.ours?scorer(true):['Liam Foster','Marco Silva','Elliot James','Drew Cooper'][Math.floor(Math.random()*4)]})}events.sort((a,b)=>a.minute-b.minute);const ourGame=results.find(m=>m.home==='Riverside FC'||m.away==='Riverside FC');state.played.push(...results);const won=ourGame.home==='Riverside FC'?ourGame.hg>ourGame.ag:ourGame.ag>ourGame.hg,draw=ourGame.hg===ourGame.ag;state.players.forEach(p=>{p.fitness=Math.max(48,p.fitness-(state.lineup.includes(p.id)?5:2));p.morale=Math.max(45,Math.min(100,p.morale+(draw?1:won?4:-3)+(state.lineup.includes(p.id)?1:0)))});state.round++;state.lastNews=won?'A superb result for Riverside. The players will be buzzing.':draw?'A hard-fought point for Riverside.':'A disappointing result, but there is time to respond.';save();openMatch(ourGame,events)}
function scorer(ours){const choices=state.lineup.map(player).filter(p=>p&&(['ATT','MID'].includes(p.pos)));return (choices.length?choices:[...state.lineup.map(player).filter(Boolean)]).sort((a,b)=>b.rating-a.rating)[Math.floor(Math.random()*Math.min(choices.length||1,3))]?.name||'Riverside FC'}
function openMatch(match,events){const home=match.home==='Riverside FC'?clubs[0]:clubs.find(c=>c.name===match.home),away=match.away==='Riverside FC'?clubs[0]:clubs.find(c=>c.name===match.away);const relevant=events.filter(e=>e.team.name===match.home||e.team.name===match.away);const eventMarkup=relevant.length?relevant.map(e=>`<div class="event-line goal"><span class="event-minute">${e.minute}'</span><span class="event-icon">⚽</span><span class="event-copy"><strong>${escapeHtml(e.name)}</strong> scores for ${escapeHtml(e.team.name)}</span></div>`).join(''):`<div class="event-line dim"><span class="event-minute">90'</span><span class="event-icon">◌</span><span class="event-copy">A tense, goalless afternoon at the ground.</span></div>`;const modal=document.getElementById('match-modal');modal.innerHTML=`<div class="match-modal-top"><span>NORTHBRIDGE LEAGUE · MATCHDAY ${String(match.round).padStart(2,'0')}</span><button data-action="close-match" aria-label="Close">×</button></div><div class="scoreboard"><div class="score-team"><div class="team-crest">${home?.crest||'⚽'}</div><strong>${escapeHtml(match.home)}</strong></div><div class="score-number">${match.hg} – ${match.ag}<small>FULL TIME</small></div><div class="score-team"><div class="team-crest opponent">${away?.crest||'⚽'}</div><strong>${escapeHtml(match.away)}</strong></div></div><div class="match-events">${eventMarkup}<div class="event-line dim"><span class="event-minute">90'</span><span class="event-icon">⌁</span><span class="event-copy">The final whistle blows. ${escapeHtml(state.lastNews)}</span></div></div><div class="match-modal-bottom"><span>Matchday ${match.round} complete · Progress saved</span><button class="button primary small" data-action="close-match">Continue&nbsp; →</button></div>`;document.getElementById('modal-backdrop').classList.add('open');document.getElementById('modal-backdrop').setAttribute('aria-hidden','false')}
function closeMatch(){document.getElementById('modal-backdrop').classList.remove('open');document.getElementById('modal-backdrop').setAttribute('aria-hidden','true');render()}
function bindViewEvents(){document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{activeView=b.dataset.view;render()});document.querySelectorAll('#play-match').forEach(b=>b.onclick=simulateMatch);document.querySelectorAll('[data-action="training"]').forEach(b=>b.onclick=train);document.querySelectorAll('[data-select-player]').forEach(b=>b.onclick=()=>selectPlayer(Number(b.dataset.selectPlayer)));document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>buyPlayer(Number(b.dataset.buy)));document.querySelectorAll('[data-action="save-tactics"]').forEach(b=>b.onclick=saveTactics);document.querySelectorAll('[data-action="close-match"]').forEach(b=>b.onclick=closeMatch);const search=document.getElementById('player-search'),filter=document.getElementById('position-filter');if(search)search.oninput=()=>{const rows=document.getElementById('squad-rows');rows.innerHTML=squadRows(filter.value,search.value);bindViewEvents()};if(filter)filter.onchange=()=>{const rows=document.getElementById('squad-rows');rows.innerHTML=squadRows(filter.value,search.value);bindViewEvents()};['formation','mentality','press','focus','training'].forEach(id=>{const el=document.getElementById(id);if(el)el.onchange=()=>{if(id==='training')state.training=el.value;else state.tactic[id]=el.value;save()}})}
function saveTactics(){['formation','mentality','press','focus','training'].forEach(id=>{const el=document.getElementById(id);if(el){if(id==='training')state.training=el.value;else state.tactic[id]=el.value}});save();render();showToast('Tactics saved for matchday')}
function buyPlayer(index){const prospect=marketPlayers[index];if(!prospect||state.budget<prospect.value)return;const p={...prospect,id:Math.max(...state.players.map(x=>x.id))+1,fitness:92,morale:76};state.players.push(p);state.budget=+(state.budget-prospect.value).toFixed(1);marketPlayers.splice(index,1);save();render();showToast(`${p.name} has signed for Riverside FC`)}
function resetCareer(){if(!window.confirm('Start a new Riverside FC career? Your current save will be replaced.'))return;state=structuredClone(initialState);localStorage.removeItem('touchline-save');activeView='overview';render();showToast('A fresh season awaits, boss')}
document.getElementById('reset-save').addEventListener('click',resetCareer);document.getElementById('modal-backdrop').addEventListener('click',e=>{if(e.target.id==='modal-backdrop')closeMatch()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.getElementById('modal-backdrop').classList.contains('open'))closeMatch()});document.querySelector('.brand').addEventListener('click',e=>{e.preventDefault();activeView='overview';render()});render();

